import unittest

from solution import sum_measurements


class SumMeasurementsTests(unittest.TestCase):
    def test_signed_values_whitespace_and_blanks(self):
        lines = ["  +12  ", "", " \t ", "-7", "0005", " 0\n"]
        snapshot = lines[:]
        self.assertEqual(sum_measurements(lines), (10, 4))
        self.assertEqual(lines, snapshot)

    def test_empty_and_all_blank_inputs(self):
        self.assertEqual(sum_measurements([]), (0, 0))
        self.assertEqual(sum_measurements(iter([" ", "\n", "\t"])), (0, 0))

    def test_one_shot_iterable_is_consumed_once(self):
        class Once:
            def __init__(self):
                self.iterations = 0

            def __iter__(self):
                self.iterations += 1
                if self.iterations > 1:
                    raise AssertionError("iterated more than once")
                yield "1"
                yield "2"

        source = Once()
        self.assertEqual(sum_measurements(source), (3, 2))
        self.assertEqual(source.iterations, 1)

    def test_invalid_outer_values(self):
        for value in ("12", b"12", 12, None):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    sum_measurements(value)

    def test_non_string_element(self):
        with self.assertRaises(TypeError):
            sum_measurements(["1", 2])

    def test_invalid_integer_reports_zero_based_position(self):
        with self.assertRaises(ValueError) as caught:
            sum_measurements(["10", " ", "not-an-integer", "20"])
        self.assertIn("2", str(caught.exception))

    def test_invalid_value_does_not_request_later_input(self):
        def records():
            yield "4"
            yield "bad"
            raise AssertionError("later input was requested")

        with self.assertRaises(ValueError) as caught:
            sum_measurements(records())
        self.assertIn("1", str(caught.exception))


if __name__ == "__main__":
    unittest.main()

